//! The «Help» windows: «Keyboard shortcuts» (F1) and «About revisor». Each is a read-only
//! text field, so the text can be read with the arrow keys and copied, and a Close button;
//! Esc closes the window too.

use wxdragon::prelude::*;

use crate::commands::CommandId;
use crate::i18n::Strings;
use crate::menus::shortcuts_text;

/// The licences of the third-party crates in the exe, generated by cargo-about (TASK-18).
const THIRD_PARTY_LICENSES: &str = include_str!("../THIRD-PARTY-LICENSES.txt");

pub fn show_shortcuts(parent: &Frame, s: &'static dyn Strings) {
    show_text(
        parent,
        s,
        s.command(CommandId::KeyboardShortcuts),
        &shortcuts_text(s),
    );
}

pub fn show_about(parent: &Frame, s: &'static dyn Strings) {
    let text = format!(
        "{}\n{THIRD_PARTY_LICENSES}",
        s.about(revisor_core::version())
    );
    show_text(parent, s, s.command(CommandId::About), &text);
}

fn show_text(parent: &Frame, s: &'static dyn Strings, title: &str, text: &str) {
    let dialog = Dialog::builder(parent, title)
        .with_style(DialogStyle::DefaultDialogStyle | DialogStyle::ResizeBorder)
        .with_size(640, 480)
        .build();
    let field = TextCtrl::builder(&dialog)
        .with_style(TextCtrlStyle::MultiLine | TextCtrlStyle::ReadOnly | TextCtrlStyle::DontWrap)
        .build();
    field.set_value(text);
    field.set_insertion_point(0);
    // The dialog's Cancel: Esc presses it, and as in other dialogs it has no access key.
    let close = Button::builder(&dialog)
        .with_id(ID_CANCEL)
        .with_label(s.close())
        .build();
    dialog.set_escape_id(ID_CANCEL);

    let sizer = BoxSizer::builder(Orientation::Vertical).build();
    sizer.add(&field, 1, SizerFlag::Expand | SizerFlag::All, 8);
    sizer.add(
        &close,
        0,
        SizerFlag::AlignRight | SizerFlag::Left | SizerFlag::Right | SizerFlag::Bottom,
        8,
    );
    dialog.set_sizer(sizer, true);
    dialog.centre();
    field.set_focus();
    dialog.show_modal();
    // A plain wxDragon Dialog is not destroyed when dropped.
    dialog.destroy();
}
